python - <<'PY'
import cv2,numpy as np,time
P=np.load('/app/output/parts.npz')['parts'].astype(np.uint8); T=(cv2.imread('/app/target.png',0)<128).astype(np.uint8)
base=np.load('/app/output/offsets.npy'); offsets=base.copy(); radii=np.zeros(16,dtype=int)
def morph(m,r):
 if r==0:return m
 k=cv2.getStructuringElement(cv2.MORPH_ELLIPSE,(2*abs(r)+1,2*abs(r)+1))
 return cv2.dilate(m,k) if r>0 else cv2.erode(m,k)
def shift(m,dy,dx):
 out=np.zeros_like(m); y0=max(0,dy);y1=min(1024,1024+dy);x0=max(0,dx);x1=min(1024,1024+dx)
 if y1>y0 and x1>x0: out[y0:y1,x0:x1]=m[y0-dy:y1-dy,x0-dx:x1-dx]
 return out
def union_all():
 a=np.zeros_like(T)
 for i in range(16):a|=shift(morph(P[i],int(radii[i])),int(offsets[i,0]),int(offsets[i,1]))
 return a
def iou(a):
 inter=(a&T).sum();return inter/(a.sum()+T.sum()-inter)
for pas in range(2):
 for i in range(16):
  other=np.zeros_like(T)
  for j in range(16):
   if j!=i:other|=shift(morph(P[j],int(radii[j])),int(offsets[j,0]),int(offsets[j,1]))
  best=(-1,None,None,None)
  for r in range(-3,4):
   m=morph(P[i],r)
   for dy in range(int(base[i,0])-3,int(base[i,0])+4):
    for dx in range(int(base[i,1])-3,int(base[i,1])+4):
     a=other|shift(m,dy,dx);val=iou(a)
     if val>best[0]:best=(val,dy,dx,r)
  _,dy,dx,r=best;offsets[i]=[dy,dx];radii[i]=r
 print('pass',pas,'iou',iou(union_all()),'offsets',offsets.tolist(),'r',radii.tolist())
a=union_all();cv2.imwrite('/app/output/optimized_parts.png',a*255)
# eval best register
pad=cv2.copyMakeBorder(a,22,22,22,22,cv2.BORDER_CONSTANT,value=0);C=cv2.matchTemplate(pad,T,cv2.TM_CCORR);y,x=np.unravel_index(C.argmax(),C.shape);inter=float(C[y,x]);print('best reg',x-22,y-22,'iou',inter/(a.sum()+T.sum()-inter),'area',int(a.sum()))
np.savez_compressed('/app/output/optim.npz',offsets=offsets,radii=radii)
PY

